import { expect, expectStatus, test } from "../../fixtures";

test("rejecting one document sends the whole vendor back", { tag: "@LIF-02" }, async ({ factory, apiAs }) => {
  // Arrange: a vendor in review with three pending extractions
  const { vendor, documents, extractions } = await factory.vendorInReview({ as: "member" });
  const reviewer = await apiAs("reviewer");
  const contract = extractions.contract;

  // Act: the reviewer rejects the contract extraction with a note
  const decision = await reviewer.post(`/api/extractions/${contract.id}/decision`, {
    data: { decision: "reject", note: "Wrong counterparty" },
  });
  await expectStatus(decision, 200);

  // Assert: the stored extraction and the vendor reflect the rejection
  const storedExtraction = await factory.extraction(documents.contract.id, "reviewer");
  expect(storedExtraction.status).toBe("rejected");
  expect(storedExtraction.review_note).toBe("Wrong counterparty");

  const storedVendor = await expectStatus<{ status: string }>(await reviewer.get(`/api/vendors/${vendor.id}`), 200);
  expect(storedVendor.status).toBe("rejected");

  const trail = await expectStatus<{ items: { action: string }[] }>(
    await reviewer.get(`/api/vendors/${vendor.id}/audit`),
    200,
  );
  const lifecycleActions = trail.items
    .map((event) => event.action)
    .filter((action) => action === "extraction.rejected" || action === "vendor.rejected");
  expect(lifecycleActions).toEqual(["extraction.rejected", "vendor.rejected"]);
});
